/** The official gold Noor lockup (نور over "noor"), rendered inline. */
export function NoorLogoArt({ className }: { className?: string }) {
  return <span className={className} aria-label="Maison Noor" role="img" dangerouslySetInnerHTML={{ __html: LOGO }} />;
}

/** The نور calligraphy flourish, rendered inline (decorative). */
export function NoorArabicArt({ className }: { className?: string }) {
  return <span className={className} aria-hidden="true" dangerouslySetInnerHTML={{ __html: ARABIC }} />;
}

/** The Algerian oasis engraving, rendered inline (decorative). */
export function NoorOasisArt({ className }: { className?: string }) {
  return <span className={className} aria-hidden="true" dangerouslySetInnerHTML={{ __html: OASIS }} />;
}
